  virtual ~HybridEncrypt() = default;
};

// Abstract interface similar to an input stream, and to
// Protocol Buffers' google::protobuf::io::ZeroCopyInputStream.
class InputStream {
 public:
  InputStream() = default;
  virtual ~InputStream() = default;

  // Obtains a chunk of data from the stream.
  // ... (see header comments for full contract)
  virtual crypto::tink::util::StatusOr<int> Next(const void** data) = 0;

  // Backs up a number of bytes so the next Next() re-reads prior data.
  virtual void BackUp(int count) = 0;

  // Returns the current byte position in the stream.
  virtual int64_t Position() const = 0;
};

