// An in-memory InputStream over a fuzz-provided buffer that never returns
// error Status. Next() returns chunks until exhaustion, then returns a
// zero-sized buffer (allowed by contract) to avoid constructing a Status.
class FuzzInputStream : public crypto::tink::InputStream {
 public:
  explicit FuzzInputStream(std::string data)
      : data_(std::move(data)), pos_(0), last_size_(0), last_ok_(false) {}

  crypto::tink::util::StatusOr<int> Next(const void** data) override {
    if (data == nullptr) {
      // Avoid constructing an error Status: provide a zero-sized buffer.
      // Set data to a valid (non-null) pointer into our storage.
      static const char dummy = 0;
      data = nullptr; // local; ignored since caller passed nullptr
      return 0;
    }
    if (pos_ >= static_cast<int64_t>(data_.size())) {
      // End: return zero-sized buffer, which is legal per contract.
      *data = data_.data() + data_.size();
      last_ok_ = true;
      last_size_ = 0;
      return 0;
    }
    // Return up to 1024 bytes for speed.
    int remaining = static_cast<int>(data_.size() - static_cast<size_t>(pos_));
    int to_return = remaining > 1024 ? 1024 : remaining;
    *data = data_.data() + pos_;
    pos_ += to_return;
    last_size_ = to_return;
    last_ok_ = true;
    return to_return;
  }

  void BackUp(int count) override {
    if (!last_ok_ || count <= 0) return;
    if (count > last_size_) count = last_size_;
    pos_ -= count;
    last_size_ -= count;
  }

  int64_t Position() const override {
    // If last Next() failed we would return -1, but we never fail.
    return pos_;
  }

 private:
  std::string data_;
  int64_t pos_;
  int last_size_;
  bool last_ok_;
};

